import * as THREE from './vendor/three.module.min.js';
import {parts,profiles,sources,getProfile,connections,bom,pinAssignments,arduinoSketch,plan} from './circuit-data.js';
const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let profile=getProfile(new URLSearchParams(location.search).get('device')),selected='controller',step=-1,mode='assembled',showWires=true,toastTimer,drag=null;
let view=null;
function element(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
function notify(text){$('circuit-toast').textContent=text;$('circuit-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('circuit-toast').classList.remove('show'),3200);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=element('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Downloaded '+name);}
const csv=rows=>rows.map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(',')).join('\r\n');
const tabButtons=profiles.map((p,i)=>{const button=element('button');button.setAttribute('role','tab');button.setAttribute('id',`application-${p.id}`);button.setAttribute('aria-controls','steps');button.innerHTML=`<span>0${i+1}</span><div><strong>${p.name}</strong><small>${p.subtitle}</small></div>`;button.addEventListener('click',()=>chooseProfile(p.id));button.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%5;if(e.key==='ArrowLeft')n=(i+4)%5;if(e.key==='Home')n=0;if(e.key==='End')n=4;if(n!==undefined){e.preventDefault();chooseProfile(profiles[n].id);tabButtons[n].focus();}});$('application-tabs').append(button);return button;});
function chooseProfile(id){profile=getProfile(id);selected='controller';step=-1;history.replaceState(null,'',`circuit.html?device=${profile.id}`);renderProfile();view?.rebuild();}
function inspect(id){if(!profile.parts.includes(id))return;selected=id;if(step>=0)step=profile.parts.indexOf(id);renderSelection();view?.updateParts();}
function renderProfile(){document.documentElement.style.setProperty('--accent',profile.color);document.title=`Orbit — ${profile.name} Circuit Workshop`;$('view-profile').textContent=profile.name.toUpperCase();$('profile-description').textContent=profile.behavior;$('lab-link').href=`lab.html?device=${profile.id}`;tabButtons.forEach((b,i)=>{b.setAttribute('aria-selected',String(profiles[i].id===profile.id));b.tabIndex=profiles[i].id===profile.id?0:-1;});$('steps').replaceChildren(...profile.parts.map((id,i)=>{const b=element('button',undefined,'step');b.dataset.part=id;b.innerHTML=`<span class="step-num">${String(i+1).padStart(2,'0')}</span><span><strong>${parts[id].short}</strong><small>${parts[id].ref}</small></span>`;b.addEventListener('click',()=>inspect(id));return b;}));$('connection-filter').replaceChildren(new Option('All components','all'),...profile.parts.filter(id=>parts[id].wires.length).map(id=>new Option(parts[id].name,id)));renderWiring();$('bom-body').replaceChildren(...bom(profile).map(row=>{const tr=element('tr');tr.append(element('td',row.quantity),element('td',row.item));return tr;}));$('arduino-code').textContent=arduinoSketch(profile);$('library-list').replaceChildren(...profile.libraries.map(name=>element('li',name)));$('pcb-rules').replaceChildren(...profile.parts.map(id=>{const li=element('li');const strong=element('strong',parts[id].short+': ');li.append(strong,document.createTextNode(parts[id].placement));return li;}));renderSelection();}
function renderSelection(){const p=parts[selected];$('part-ref').textContent=`${String(profile.parts.indexOf(selected)+1).padStart(2,'0')} / ${p.ref}`;$('part-name').textContent=p.name;$('part-supply').textContent=p.supply;for(const key of ['spec','role','placement','assembly','check'])$('part-'+key).textContent=p[key];$('part-sources').replaceChildren(...p.sources.map(id=>{const a=element('a',sources[id].title+' ↗');a.href=sources[id].url;a.target='_blank';a.rel='noopener';return a;}));document.querySelectorAll('.step').forEach((b,i)=>{b.classList.toggle('active',b.dataset.part===selected);b.classList.toggle('complete',step>=0&&i<step);b.classList.toggle('future',step>=0&&i>step);b.setAttribute('aria-pressed',String(b.dataset.part===selected));});$('previous-step').disabled=step<=0;$('next-step').textContent=step<0?'Start build →':step===profile.parts.length-1?'Finish build ✓':'Next component →';$('step-counter').textContent=step<0?'Explore the full assembly':`Step ${step+1} of ${profile.parts.length}`;$('build-count').textContent=step<0?'All components visible':`${step+1} / ${profile.parts.length} stages shown`;$('start-build').innerHTML=step<0?'Circuit <span>Start guided build →</span>':'Circuit <span>Restart from step 1 ↺</span>';document.querySelectorAll('.part-label').forEach(b=>b.classList.toggle('active',b.dataset.part===selected));}
function start(){step=0;selected=profile.parts[0];mode='assembled';renderSelection();syncModes();view?.updateParts();}
$('start-build').addEventListener('click',start);$('previous-step').addEventListener('click',()=>{if(step>0){step--;selected=profile.parts[step];renderSelection();view?.updateParts();}});$('next-step').addEventListener('click',()=>{if(step<0){start();return;}if(step<profile.parts.length-1){step++;selected=profile.parts[step];}else{step=-1;notify('Assembly guide complete. Verify every connection before powering the real hardware.');}renderSelection();view?.updateParts();});
function syncModes(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));view?.setMode(mode);}
for(const b of document.querySelectorAll('[data-mode]'))b.addEventListener('click',()=>{mode=b.dataset.mode;syncModes();});$('reset-camera').addEventListener('click',()=>view?.reset());$('show-wires').addEventListener('change',e=>{showWires=e.target.checked;view?.updateParts();});
function renderWiring(){const filter=$('connection-filter').value||'all';$('wire-caption').textContent=profile.name+' / '+(filter==='all'?'all connections':parts[filter].name);$('wiring-body').replaceChildren(...connections(profile).filter(row=>filter==='all'||row.component===filter).map(row=>{const tr=element('tr');for(const value of [parts[row.component].short,row.from,row.to,row.net,row.note])tr.append(element('td',value));return tr;}));const core=element('div','ESP32-S3','bus-core'),branches=element('div',undefined,'bus-branches');for(const id of profile.parts.filter(id=>id!=='controller'&&id!=='power')){const b=element('button');b.append(document.createTextNode(parts[id].short),element('span',parts[id].supply));b.addEventListener('click',()=>{inspect(id);$('connection-filter').value=id;renderWiring();});branches.append(b);}$('bus-diagram').replaceChildren(core,element('span','↔'),branches,element('span','LOGICAL BLOCK MAP · Some paths pass through drivers. Use the table for exact endpoints.','bus-note'));}
$('connection-filter').addEventListener('change',renderWiring);
const docTabs=[...document.querySelectorAll('[data-doc]')];function selectDoc(name){docTabs.forEach(b=>{const active=b.dataset.doc===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;$('doc-'+b.dataset.doc).hidden=!active;});}
docTabs.forEach((b,i)=>{b.addEventListener('click',()=>selectDoc(b.dataset.doc));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%docTabs.length;if(e.key==='ArrowLeft')n=(i+docTabs.length-1)%docTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=docTabs.length-1;if(n!==undefined){e.preventDefault();selectDoc(docTabs[n].dataset.doc);docTabs[n].focus();}});});
$('export-plan').addEventListener('click',()=>download(`orbit-${profile.id}-build-plan.json`,JSON.stringify(plan(profile),null,2),'application/json'));
$('export-wires').addEventListener('click',()=>download(`orbit-${profile.id}-wiring.csv`,csv([['Component','From','To','Signal','Note'],...connections(profile).map(r=>[parts[r.component].name,r.from,r.to,r.net,r.note])]),'text/csv'));
$('export-bom').addEventListener('click',()=>download(`orbit-${profile.id}-parts.csv`,csv([['Quantity','Part'],...bom(profile).map(r=>[r.quantity,r.item])]),'text/csv'));
$('export-arduino').addEventListener('click',()=>download(`orbit_${profile.id}_bringup.ino`,arduinoSketch(profile),'text/plain'));

