 canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(7,Math.min(22,distance+e.deltaY*.006));},{passive:false});canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')theta-=.15;if(e.key==='ArrowRight')theta+=.15;if(e.key==='ArrowUp')targetPhi=Math.max(.04,targetPhi-.12);if(e.key==='ArrowDown')targetPhi=Math.min(1.45,targetPhi+.12);if(e.key==='+')distance=Math.max(7,distance-.6);if(e.key==='-')distance=Math.min(22,distance+.6);});
