 let last=0;function tick(now){if(disposed)return;requestAnimationFrame(tick);if(document.hidden||now-last<32)return;last=now;const old=explosion;explosion=THREE.MathUtils.lerp(explosion,targetExplosion,reduced?1:.15);phi=THREE.MathUtils.lerp(phi,targetPhi,reduced?1:.15);camera.position.set(Math.sin(theta)*Math.sin(phi)*distance,Math.cos(phi)*distance,Math.cos(theta)*Math.sin(phi)*distance);camera.lookAt(0,.2,0);for(const [id,g] of groups){const b=g.userData.base;g.position.set(b.x,b.y+explosion*g.userData.height,b.z);g.userData.halo.update();}if(Math.abs(old-explosion)>.0001)redrawWires();root.updateMatrixWorld();camera.updateMatrixWorld();const r=wrap.getBoundingClientRect();for(const [id,g] of groups){if(!g.visible)continue;const v=new THREE.Vector3(g.position.x,g.position.y+.35,g.position.z+parts[id].size[2]/2+.12).project(camera);const label=labels.get(id);label.style.left=(v.x*.5+.5)*r.width+'px';label.style.top=(-v.y*.5+.5)*r.height+'px';label.style.opacity=v.z>1?'0':'1';}renderer.render(scene,camera);}
